style.css:
@-moz-document domain("soundcloud.com") {
/* Основной фон */
  body {
    background-color: #0a0a0a !important;
    color: #ffffff !important;
  }
  
  /* Навигационная панель */
  .header,
  .sc-classic .header,
  .sc-border-box {
    background-color: #1a1a1a !important;
    border-bottom: 1px solid #333 !important;
  }
  
  /* Карточки треков */
  .sound__body,
  .sc-classic .sound__body,
  .sc-border-box {
    background-color: #1e1e1e !important;
    border: 1px solid #333 !important;
    border-radius: 8px !important;
  }
  
  /* Заголовки треков */
  .soundTitle__title,
  .sc-classic .soundTitle__title {
    color: #ffffff !important;
  }
  
  /* Имена пользователей */
  .soundTitle__username,
  .sc-classic .soundTitle__username {
    color: #b3b3b3 !important;
  }
  
  /* Кнопки */
  .sc-button,
  .sc-classic .sc-button {
    background-color: #ff5500 !important;
    color: white !important;
    border-radius: 4px !important;
    border: none !important;
  }
  
  .sc-button:hover {
    background-color: #ff7700 !important;
  }
  
  /* Плеер */
  .playControls,
  .sc-classic .playControls {
    background-color: #1a1a1a !important;
    border-top: 1px solid #333 !important;
  }
  
  /* Прогресс-бар */
  .playbackTimeline__progressWrapper,
  .sc-classic .playbackTimeline__progressWrapper {
    background-color: #333 !important;
  }
  
  .playbackTimeline__progressBackground,
  .sc-classic .playbackTimeline__progressBackground {
    background-color: #ff5500 !important;
  }
  
  /* Громкость */
  .volume__sliderWrapper,
  .sc-classic .volume__sliderWrapper {
    background-color: #333 !important;
  }
  
  .volume__sliderBackground,
  .sc-classic .volume__sliderBackground {
    background-color: #ff5500 !important;
  }
  
  /* Сайдбар */
  .l-sidebar,
  .sc-classic .l-sidebar {
    background-color: #151515 !important;
    border-right: 1px solid #333 !important;
  }
  
  /* Ссылки в сайдбаре */
  .g-tabs-link,
  .sc-classic .g-tabs-link {
    color: #b3b3b3 !important;
  }
  
  .g-tabs-link:hover {
    color: #ffffff !important;
    background-color: #2a2a2a !important;
  }
  
  /* Поисковая строка */
  .headerSearch__input,
  .sc-classic .headerSearch__input {
    background-color: #2a2a2a !important;
    color: white !important;
    border: 1px solid #444 !important;
  }
  
  /* Аватарки */
  .userBadge__image,
  .sc-classic .userBadge__image {
    border-radius: 50% !important;
  }
  
  /* Статистика */
  .sc-ministats,
  .sc-classic .sc-ministats {
    color: #888 !important;
  }
  
  /* Время трека */
  .playbackTimeline__time,
  .sc-classic .playbackTimeline__time {
    color: #b3b3b3 !important;
  }
}
